<?php
const PRESENCE_TTL=45000;
function group_info(string $id,bool $lock=false): array {$g=one('SELECT g.id,g.name,g.invite_code AS code,g.owner_id AS ownerId,g.background_continue AS backgroundContinue,g.background_minutes AS backgroundMinutes,g.deleted_at AS deletedAt,g.is_private AS isPrivate,g.is_personal AS isPersonal,g.camera_required AS cameraRequired,g.created_at AS createdAt,u.display_name AS ownerName FROM '.table('study_groups').' g JOIN '.table('users').' u ON u.id=g.owner_id WHERE g.id=?'.($lock?' FOR UPDATE':''),[$id]);if(!$g)fail(404,'GROUP_NOT_FOUND','این گروه پیدا نشد.');$g['isPrivate']=(bool)$g['isPrivate'];$g['isPersonal']=(bool)$g['isPersonal'];$g['cameraRequired']=(bool)$g['cameraRequired'];$g['backgroundContinue']=(bool)$g['backgroundContinue'];$g['backgroundMinutes']=(int)$g['backgroundMinutes'];return $g;}
function membership(string $id,string $uid): ?array {return one('SELECT status FROM '.table('group_members').' WHERE group_id=? AND user_id=?',[$id,$uid]);}
function member_required(string $id,string $uid): void {$room=one('SELECT archived,deleted_at FROM '.table('study_groups').' WHERE id=?',[$id]);if(!empty($room['deleted_at']))fail(404,'GROUP_DELETED','این گروه حذف شده است.');if(!empty($room['archived']))fail(403,'GROUP_ARCHIVED','این اتاق توسط مدیر سایت بایگانی شده است؛ تاریخچه محفوظ است.');$m=membership($id,$uid);if(($m['status']??'')!=='approved')fail(403,($m['status']??'')==='kicked'?'REMOVED':'NOT_APPROVED',($m['status']??'')==='kicked'?'مدیر، تو را از گروه خارج کرده است.':'ورودت هنوز توسط مدیر تأیید نشده است.');}
function group_snapshot(string $id,string $uid): array {
 $g=group_info($id);member_required($id,$uid);$time=now_ms();
 $members=rows("SELECT m.user_id AS userId,u.display_name AS name,(m.user_id=g.owner_id) AS isOwner,(r.user_id IS NOT NULL) AS online,COALESCE(r.active_ms,0) AS activeMs,COALESCE(r.studying,0) AS studying,COALESCE(r.run_until,0) AS runUntil,(COALESCE(r.run_until,0)>? AND r.last_seen<?) AS background,COALESCE(r.mode,'manual') AS mode,(SELECT COALESCE(SUM(h.active_ms),0) FROM ".table('room_history')." h WHERE h.group_id=m.group_id AND h.user_id=m.user_id) AS totalMs FROM ".table('group_members').' m JOIN '.table('users').' u ON u.id=m.user_id JOIN '.table('study_groups').' g ON g.id=m.group_id LEFT JOIN '.table('room_presence')." r ON r.user_id=m.user_id AND (r.group_id=m.group_id OR EXISTS(SELECT 1 FROM ".table('credit_heads')." ch WHERE ch.visit_id=r.visit_id AND ch.companion_id=m.group_id)) AND (r.last_seen>=? OR r.run_until>?) WHERE m.group_id=? AND m.status='approved' ORDER BY isOwner DESC,u.display_name",[$time,$time-PRESENCE_TTL,$time-PRESENCE_TTL,$time,$id]);
 foreach($members as &$m){$totals=progress_totals($m['userId'],$id);$m['dailyMs']=$totals['dailyMs'];$m['weeklyMs']=$totals['weeklyMs'];$m['isOwner']=(bool)$m['isOwner'];$m['online']=(bool)$m['online'];$m['studying']=(bool)$m['studying'];$m['background']=(bool)$m['background'];$m['activeMs']=(int)$m['activeMs'];$m['totalMs']=$totals['totalMs'];$m['isSelf']=$m['userId']===$uid;}unset($m);
 $requests=$g['ownerId']===$uid?rows('SELECT m.user_id AS userId,u.display_name AS name,m.requested_at AS requestedAt FROM '.table('group_members').' m JOIN '.table('users')." u ON u.id=m.user_id WHERE m.group_id=? AND m.status='pending' ORDER BY m.requested_at",[$id]):[];
 $history=rows('SELECT h.visit_id AS visitId,u.display_name AS name,h.active_ms AS activeMs,h.entered_at AS enteredAt,h.last_seen AS lastSeen,h.mode FROM '.table('room_history').' h JOIN '.table('users').' u ON u.id=h.user_id WHERE h.group_id=? ORDER BY h.last_seen DESC LIMIT 100',[$id]);
 if($g['isPrivate'])$history=rows('SELECT c.visit_id AS visitId,u.display_name AS name,SUM(c.active_ms) AS activeMs,MIN(c.started_at) AS enteredAt,MAX(c.ended_at) AS lastSeen,\'shared\' AS mode FROM '.table('study_credits').' c JOIN '.table('users').' u ON u.id=c.user_id WHERE c.group_id=? OR c.companion_id=? GROUP BY c.visit_id,c.user_id,u.display_name ORDER BY lastSeen DESC LIMIT 100',[$id,$id]);
 $overall=progress_totals($uid);$head=one('SELECT c.companion_id FROM '.table('credit_heads').' c JOIN '.table('room_presence').' r ON r.visit_id=c.visit_id WHERE r.user_id=?',[$uid]);
 return ['period'=>$overall['period'],'group'=>$g,'history'=>$history,'serverNow'=>$time,'members'=>$members,'requests'=>$requests,'me'=>['userId'=>$uid,'isOwner'=>$g['ownerId']===$uid,'overallDailyMs'=>$overall['dailyMs'],'overallWeeklyMs'=>$overall['weeklyMs'],'companionId'=>$head['companion_id']??'']];
}
