 }
 if($path==='/groups/join'&&$method==='POST'){
  $code=strtoupper(preg_replace('/[\s-]/','',(string)($data['code']??'')));if(!preg_match('/^[A-Z2-9]{10}$/D',$code))fail(422,'INVALID_CODE','کد ۱۰ کاراکتری گروه را وارد کن.');
  begin_write();try{$g=one('SELECT id,name FROM '.table('study_groups').' WHERE invite_code=? AND deleted_at=0 AND is_personal=0 FOR UPDATE',[$code]);if(!$g)fail(404,'GROUP_NOT_FOUND','گروهی با این کد پیدا نشد.');if(!empty(one('SELECT archived FROM '.table('study_groups').' WHERE id=?',[$g['id']])['archived']))fail(403,'GROUP_ARCHIVED','این گروه بایگانی شده است.');$m=membership($g['id'],$uid);if(in_array($m['status']??'',['approved','pending'],true)){$status=$m['status'];}else{$count=one('SELECT COUNT(*) AS n FROM '.table('group_members')." WHERE group_id=? AND status IN ('approved','pending')",[$g['id']]);if($count['n']>=150)fail(409,'REQUEST_LIMIT','ظرفیت درخواست‌های گروه پر شده است.');query('INSERT INTO '.table('group_members')." (group_id,user_id,status,requested_at,updated_at) VALUES (?,?,'pending',?,?) ON DUPLICATE KEY UPDATE status='pending',requested_at=VALUES(requested_at),updated_at=VALUES(updated_at)",[$g['id'],$uid,$time,$time]);$status='pending';}db()->commit();return ['group'=>$g,'status'=>$status];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
 }
 if($path==='/personal/enter'&&$method==='POST'){
  begin_write();try{one('SELECT id FROM '.table('users').' WHERE id=? FOR UPDATE',[$uid]);$personal=one('SELECT group_id FROM '.table('personal_rooms').' WHERE user_id=?',[$uid]);if(!$personal){$pid=ident();$code=strtoupper(substr(bin2hex(random_bytes(8)),0,10));query('INSERT INTO '.table('study_groups')." (id,name,invite_code,owner_id,created_at,is_private,is_personal) VALUES (?,'مطالعهٔ شخصی',?,?,?,1,1)",[$pid,$code,$uid,$time]);query('INSERT INTO '.table('personal_rooms').' (user_id,group_id) VALUES (?,?)',[$uid,$pid]);query('INSERT INTO '.table('group_members')." (group_id,user_id,status,requested_at,updated_at) VALUES (?,?,'approved',?,?)",[$pid,$uid,$time,$time]);}else $pid=$personal['group_id'];$visit=ident();query('INSERT INTO '.table('room_presence')." (user_id,group_id,visit_id,active_ms,studying,entered_at,last_seen) VALUES (?,?,?,0,0,?,?) ON DUPLICATE KEY UPDATE group_id=VALUES(group_id),visit_id=VALUES(visit_id),active_ms=0,studying=0,run_until=0,run_from=0,mode='manual',entered_at=VALUES(entered_at),last_seen=VALUES(last_seen)",[$uid,$pid,$visit,$time,$time]);progress_enter($visit,$uid,$pid);db()->commit();return [...group_snapshot($pid,$uid),'visitId'=>$visit];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
 }
 if($path==='/room'&&$method==='GET'){
  $presence=one('SELECT r.* FROM '.table('room_presence').' r JOIN '.table('study_groups').' g ON g.id=r.group_id WHERE r.user_id=? AND g.background_continue=1 AND g.deleted_at=0 AND g.archived=0 AND r.run_until>0',[$uid]);
  if(!$presence)return ['room'=>null];return ['room'=>array_merge(group_snapshot($presence['group_id'],$uid),['visitId'=>$presence['visit_id'],'activeMs'=>(int)$presence['active_ms'],'runUntil'=>(int)$presence['run_until']])];
 }
 if(!preg_match('~^/groups/([a-f0-9]{32})(?:/(enter|leave|heartbeat|settings|delete|restore|resume|companion)|/members/([a-f0-9]{32})/(decision|kick))?$~D',$path,$m))fail(404,'NOT_FOUND','این مسیر پیدا نشد.');
 $id=$m[1];$action=$m[2]??'';$target=$m[3]??'';$admin=$m[4]??'';
 if($method==='GET'&&!$action&&!$admin)return group_snapshot($id,$uid);if($method!=='POST')fail(405,'METHOD','این روش مجاز نیست.');
 if($action==='leave'){begin_write();try{if(isset($data['activeMs']))room_save_time($id,$uid,$data,false);query('DELETE FROM '.table('room_presence').' WHERE user_id=? AND group_id=? AND visit_id=?',[$uid,$id,(string)($data['visitId']??'')]);db()->commit();return ['left'=>true];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
 begin_write();try{
 $g=group_info($id,true);
 if($g['isPersonal']&&$action!=='heartbeat')fail(403,'PERSONAL_ROOM','فضای شخصی از بخش مطالعه مدیریت می‌شود.');
 if($action==='companion'){member_required($id,$uid);$presence=one('SELECT visit_id FROM '.table('room_presence').' WHERE user_id=? AND group_id=? AND visit_id=?',[$uid,$id,(string)($data['visitId']??'')]);if(!$presence)fail(409,'ROOM_EXPIRED','جلسهٔ فعال پیدا نشد.');$targetId=(string)($data['groupId']??'');if($targetId){$targetGroup=group_info($targetId);if(!$targetGroup['isPrivate']||$targetGroup['isPersonal']||$targetId===$id)fail(422,'PRIVATE_ONLY','گروه همراه باید اختصاصی باشد.');member_required($targetId,$uid);}query('UPDATE '.table('credit_heads').' SET companion_id=? WHERE visit_id=? AND user_id=?',[$targetId,$data['visitId'],$uid]);db()->commit();return group_snapshot($id,$uid);}
 if(in_array($action,['settings','delete','restore'],true)){
  if($g['ownerId']!==$uid)fail(403,'ADMIN_ONLY','فقط مدیر همین گروه اجازهٔ این تغییر را دارد.');
  if($action==='restore'&&!$g['deletedAt'])fail(409,'NOT_DELETED','این گروه در فهرست حذف‌شده‌ها نیست.');
  if($action==='delete'&&!$g['deletedAt'])member_required($id,$uid);
  if($action==='settings'){
   member_required($id,$uid);$name=clean_name($data['name']??null,48);$minutes=$data['backgroundMinutes']??null;if(!is_bool($data['backgroundContinue']??null)||!in_array($minutes,[15,30,60,120],true))fail(422,'POLICY','تنظیم ادامهٔ زمان معتبر نیست.');
   query('UPDATE '.table('study_groups').' SET name=?,background_continue=?,background_minutes=? WHERE id=?',[$name,$data['backgroundContinue']?1:0,$minutes,$id]);
  }else query('UPDATE '.table('study_groups').' SET deleted_at=?,archived=? WHERE id=?',[$action==='delete'?$time:0,$action==='delete'?1:0,$id]);
  progress_detach($id);query('DELETE FROM '.table('room_presence').' WHERE group_id=?',[$id]);if(function_exists('admin_log'))admin_log($uid,'group.'.$action,$id);db()->commit();return ['saved'=>true];
 }
 if(!empty($g['deletedAt']))fail(404,'GROUP_DELETED','این گروه حذف شده است.');
 if($action==='resume'){
  member_required($id,$uid);$old=one('SELECT * FROM '.table('room_presence').' WHERE user_id=? AND group_id=? AND visit_id=? AND run_until>0',[$uid,$id,(string)($data['visitId']??'')]);if(!$old)fail(409,'ROOM_EXPIRED','حضوری برای بازیابی وجود ندارد.');
  query('UPDATE '.table('room_presence').' SET run_until=0,run_from=?,studying=0,last_seen=? WHERE user_id=? AND visit_id=?',[$time,$time,$uid,$old['visit_id']]);db()->commit();return array_merge(group_snapshot($id,$uid),['visitId'=>$old['visit_id'],'activeMs'=>(int)$old['active_ms'],'runUntil'=>(int)$old['run_until']]);
 }
 if($admin){if($g['ownerId']!==$uid)fail(403,'ADMIN_ONLY','فقط سازندهٔ گروه می‌تواند اعضا را مدیریت کند.');if($target===$uid)fail(422,'OWNER_PROTECTED','مدیر گروه نمی‌تواند خودش را اخراج کند.');
  if($admin==='decision'){$decision=$data['decision']??'';if(!in_array($decision,['approve','reject'],true))fail(422,'DECISION','تصمیم معتبر نیست.');if($decision==='approve'){$count=one('SELECT COUNT(*) AS n FROM '.table('group_members')." WHERE group_id=? AND status='approved'",[$id]);if($count['n']>=50)fail(409,'GROUP_FULL','ظرفیت اعضای گروه پر است.');}$status=$decision==='approve'?'approved':'rejected';$q=query('UPDATE '.table('group_members')." SET status=?,updated_at=? WHERE group_id=? AND user_id=? AND status='pending'",[$status,$time,$id,$target]);if(!$q->rowCount())fail(409,'REQUEST_CHANGED','این درخواست دیگر در انتظار نیست.');}
  else{progress_detach($id,$target);$q=query('UPDATE '.table('group_members')." SET status='kicked',updated_at=? WHERE group_id=? AND user_id=? AND status='approved'",[$time,$id,$target]);if(!$q->rowCount())fail(409,'MEMBER_CHANGED','این فرد دیگر عضو تأییدشده نیست.');query('DELETE FROM '.table('room_presence').' WHERE group_id=? AND user_id=?',[$id,$target]);}
 }else{
  member_required($id,$uid);
  if($action==='enter'){$visit=ident();query('INSERT INTO '.table('room_presence').' (user_id,group_id,visit_id,active_ms,studying,entered_at,last_seen) VALUES (?,?,?,0,0,?,?) ON DUPLICATE KEY UPDATE group_id=VALUES(group_id),visit_id=VALUES(visit_id),active_ms=0,studying=0,run_until=0,run_from=0,mode=\'manual\',entered_at=VALUES(entered_at),last_seen=VALUES(last_seen)',[$uid,$id,$visit,$time,$time]);}
  elseif($action==='heartbeat'){room_save_time($id,$uid,$data);}
  else fail(404,'NOT_FOUND','این مسیر پیدا نشد.');
 }
 if(isset($visit))progress_enter($visit,$uid,$id);db()->commit();$result=group_snapshot($id,$uid);if(isset($visit)){$result['visitId']=$visit;}return $result;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}

function room_save_time(string $id,string $uid,array $data,bool $strict=true): void {
 $time=now_ms();$active=$data['activeMs']??null;$mode=$data['mode']??'manual';
 if(!is_int($active)||$active<0||$active>9007199254740991||!is_bool($data['studying']??null)||!is_string($data['visitId']??null))fail(422,'INVALID_TIME','اطلاعات زمان معتبر نیست.');
 if(!in_array($mode,['manual','camera','background'],true))fail(422,'MODE','روش ثبت معتبر نیست.');
 $g=group_info($id);member_required($id,$uid);if(isset($data['subjectName'])){query('UPDATE '.table('credit_heads').' SET subject_name=? WHERE visit_id=? AND user_id=?',[clean_name($data['subjectName'],40),$data['visitId'],$uid]);}if($g['cameraRequired']&&$mode!=='camera'&&$mode!=='background'&&$active>0)fail(422,'CAMERA_REQUIRED','ثبت با دوربین در این اتاق الزامی است.');
 if($mode==='background'&&!$g['backgroundContinue'])fail(422,'BACKGROUND_DISABLED','مدیر ادامهٔ زمان بیرون صفحه را مجاز نکرده است.');
 $existing=one('SELECT * FROM '.table('room_presence').' WHERE user_id=? AND group_id=? AND visit_id=?',[$uid,$id,$data['visitId']]);
 if($existing)progress_enter($data['visitId'],$uid,$id);
 if($g['backgroundContinue']&&$existing){
  if((int)$existing['last_seen']<$time-PRESENCE_TTL&&!(int)$existing['run_until']&&$strict)fail(409,'ROOM_EXPIRED','این حضور پایان یافته است؛ دوباره وارد شو.');
  $until=$data['studying']?(!empty($data['background'])&&(int)$existing['run_until']>0?(int)$existing['run_until']:$time+$g['backgroundMinutes']*60000):0;
  $saved=query('UPDATE '.table('room_presence').' SET run_until=?,run_from=?,studying=?,mode=?,last_seen=? WHERE user_id=? AND group_id=? AND visit_id=? AND last_seen<=?',[$until,$time,$until>$time?1:0,$mode,$time,$uid,$id,$data['visitId'],$time]);if($strict&&!$saved->rowCount())fail(409,'STALE_UPDATE','پیام زمان قدیمی است؛ صفحه را تازه کن.');room_settle();return;
 }
 $q=query('UPDATE '.table('room_presence').' SET mode=?,active_ms=GREATEST(active_ms,LEAST(?,GREATEST(0,?-entered_at),active_ms+GREATEST(0,?-last_seen))),studying=?,last_seen=? WHERE user_id=? AND group_id=? AND visit_id=? AND last_seen>=? AND last_seen<=?',[$mode,$active,$time,$time,$data['studying']?1:0,$time,$uid,$id,$data['visitId'],$time-PRESENCE_TTL,$time]);
 if($strict&&!$q->rowCount())fail(409,'ROOM_EXPIRED','حضورت پایان یافته؛ دوباره وارد شو. تاریخچه محفوظ است.');
 query('INSERT INTO '.table('room_history').' (visit_id,user_id,group_id,active_ms,entered_at,last_seen,mode) SELECT visit_id,user_id,group_id,active_ms,entered_at,last_seen,mode FROM '.table('room_presence')." WHERE user_id=? AND group_id=? AND visit_id=? AND active_ms>0 ON DUPLICATE KEY UPDATE active_ms=GREATEST(".table('room_history').".active_ms,VALUES(active_ms)),last_seen=VALUES(last_seen),mode=CASE WHEN ".table('room_history').".mode=VALUES(mode) THEN VALUES(mode) ELSE 'mixed' END",[$uid,$id,$data['visitId']]);progress_settle();
}
function room_upgrade(): void {
 $GLOBALS['miz_upgrade_step']='rooms';$lock=migration_lock('room');
 try {
  foreach(['study_groups'=>['camera_required','TINYINT NOT NULL DEFAULT 0'],'room_presence'=>['mode',"VARCHAR(12) NOT NULL DEFAULT 'manual'"]] as $name=>$column){
   $columns=sqlite_mode()?rows('PRAGMA table_info('.table($name).')'):rows('SHOW COLUMNS FROM '.table($name));
   if(!in_array($column[0],array_column($columns,sqlite_mode()?'name':'Field'),true))query('ALTER TABLE '.table($name).' ADD COLUMN '.$column[0].' '.$column[1]);
  }
  query('CREATE TABLE IF NOT EXISTS '.table('room_history').' (visit_id CHAR(32) PRIMARY KEY,user_id CHAR(32) NOT NULL,group_id CHAR(32) NOT NULL,active_ms BIGINT NOT NULL,entered_at BIGINT NOT NULL,last_seen BIGINT NOT NULL,mode VARCHAR(12) NOT NULL)'.migration_options());migration_unicode('room_history');
  $indexes=sqlite_mode()?rows('PRAGMA index_list('.table('room_history').')'):rows('SHOW INDEX FROM '.table('room_history'));
  $idx=config()['prefix'].'history_group_idx';if(!in_array($idx,array_column($indexes,sqlite_mode()?'name':'Key_name'),true))query('CREATE INDEX `'.$idx.'` ON '.table('room_history').'(group_id,user_id,last_seen)');
  query('INSERT INTO '.table('room_history').' (visit_id,user_id,group_id,active_ms,entered_at,last_seen,mode) SELECT r.visit_id,r.user_id,r.group_id,r.active_ms,r.entered_at,r.last_seen,r.mode FROM '.table('room_presence').' r WHERE r.active_ms>0 AND NOT EXISTS(SELECT 1 FROM '.table('room_history').' h WHERE h.visit_id=r.visit_id)');
 } finally {migration_unlock($lock);}
}

function room_settle(?string $onlyUser=null): void {
 $time=now_ms();query('UPDATE '.table('room_presence').' SET active_ms=active_ms+GREATEST(0,LEAST(?,run_until)-run_from),run_from=GREATEST(run_from,LEAST(?,run_until)),studying=CASE WHEN run_until<=? THEN 0 ELSE studying END WHERE run_until>run_from AND run_from>0 AND EXISTS(SELECT 1 FROM '.table('study_groups').' g JOIN '.table('group_members')." m ON m.group_id=g.id AND m.user_id=".table('room_presence').".user_id WHERE g.id=".table('room_presence').".group_id AND g.background_continue=1 AND g.deleted_at=0 AND g.archived=0 AND m.status='approved')".($onlyUser?' AND user_id=?':''),[$time,$time,$time,...($onlyUser?[$onlyUser]:[])]);
 query('INSERT INTO '.table('room_history').' (visit_id,user_id,group_id,active_ms,entered_at,last_seen,mode) SELECT visit_id,user_id,group_id,active_ms,entered_at,GREATEST(last_seen,run_from),CASE WHEN run_until>0 AND last_seen<? THEN \'background\' ELSE mode END FROM '.table('room_presence').' WHERE active_ms>0 '.($onlyUser?' AND user_id=?':'').' ON DUPLICATE KEY UPDATE active_ms=GREATEST('.table('room_history').'.active_ms,VALUES(active_ms)),last_seen=GREATEST('.table('room_history').'.last_seen,VALUES(last_seen)),mode=CASE WHEN '.table('room_history').'.mode=VALUES(mode) THEN VALUES(mode) ELSE \'mixed\' END',[$time-PRESENCE_TTL,...($onlyUser?[$onlyUser]:[])]);progress_settle($onlyUser);
}
